{
  "county_id": "HVA13",
  "actions": [
    {
      "action_id": "timed-pathways",
      "action": "Adopt standardised, timed cancer pathways with a fast-track referral from primary care.",
      "rationale": "The portfolio model scenario for North Savo wellbeing services county estimates 10.6 deaths postponed per year (range 1.6-21.3) at an assumed cost of EUR 372,768 a year, and the county's patients waiting over 6 months for specialised care are at 80.97 per 10 000 against 36 nationally.",
      "owner_role": "Wellbeing services county, coordinated nationally by FICAN",
      "indicator": "Patients waiting over 6 months during the year for access to specialised health care per 10 000 inhabitants",
      "roadmap_measure": "3.1.2"
    },
    {
      "action_id": "self-sampling",
      "action": "Mail an HPV self-sampling kit with the second reminder to everyone invited to cervical screening who has not attended.",
      "rationale": "Cervical screening participation in North Savo wellbeing services county is 67.83% against the 80% target, and the model scenario expects self-sampling to add 1.5-4.5 percentage points, closing about 25% of the gap.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of women invited to cervical cancer screening (smear test) who attended, %",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "screening-reminders",
      "action": "Send a second kit with plain-language, multilingual instructions to non-responders to colorectal screening and measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in North Savo wellbeing services county is 77.1% against the 80% target, and the model scenario expects reminders to add 1.5-2.9 percentage points, closing about 100% of the gap.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %",
      "roadmap_measure": "1.3.1"
    }
  ],
  "evidence_does_not_support": "The evidence does not support that these actions will reduce mortality in North Savo wellbeing services county: the timed-pathways estimate is a model scenario under stated assumptions, Danish pathway evidence is before/after without a control group, and no Finnish effect size exists for colorectal screening reminders."
}

